(* torus_trace.ml — ASSISTANT-WRITTEN STAND-IN, NOT Isabelle output.
 *
 * This file stands in for the Isabelle/HOL extraction (see
 * extraction/README.md). The real `torus_trace.ml` is generated by
 * Isabelle's `export_code` and is NOT present in this repo yet.
 *
 * This stand-in implements the same function the C reference
 * (torus_trace.c) and the AGC kernel (agc/torus_trace.agc) implement:
 * the trace of an octonion is twice its real part, t(q) = 2 * Re(q).
 * The other seven components (e1..e7) do not contribute to the trace.
 *
 * Replace this file with the real Isabelle extraction output. The
 * stand-in exists so the OCaml FFI + Obj-C router build can be
 * exercised before the extraction lands.
 *)

(* The Octonion state: Real component r + seven imaginary components. *)
type octonion_state = {
  r : int;
  e1 : int;
  e2 : int;
  e3 : int;
  e4 : int;
  e5 : int;
  e6 : int;
  e7 : int;
}

(* The trace: t(q) = 2 * Re(q). Self-addition, one ALU cycle. *)
let state_trace (s : octonion_state) : int =
  s.r + s.r
